package com.ntmdoors.item;

import com.ntmdoors.util.Biometrics;
import net.minecraft.client.util.ITooltipFlag;
import net.minecraft.entity.Entity;
import net.minecraft.item.ItemStack;
import net.minecraft.util.text.TextFormatting;
import net.minecraft.world.World;

import javax.annotation.Nullable;
import java.util.List;

/**
 * Biometric Relay Key. Works like a Relay Key - sneak right-click a blank one to generate a
 * private key - and additionally records the owner it was generated by. Its name is blue.
 *
 * <p>The biometric ID itself is not written yet; the owner already is, which is what the later
 * generation step will stamp next to the private key.</p>
 */
public class ItemBiometricRelayKey extends ItemRelayKey {

    public ItemBiometricRelayKey() {
        super("biometric_relay_key");
    }

    @Override
    protected TextFormatting nameColour() {
        return TextFormatting.AQUA;
    }

    @Override
    public void onUpdate(ItemStack stack, World world, Entity entity, int itemSlot, boolean isSelected) {
        Biometrics.tick(stack, world, entity);
    }

    @Override
    public void addInformation(ItemStack stack, @Nullable World world, List<String> tooltip, ITooltipFlag flag) {
        super.addInformation(stack, world, tooltip, flag);
        Biometrics.addOwnerLine(tooltip, stack);
    }
}
